/**
 * Bypass the simulation driver generated by Chisel (build/generated-sources/simulation-driver.cpp)
 *
 * This handles the following arguments passed to the simulator:
 * +run={cycles}: let the simulator run for a number of cycles (after the reset procedure)
 * +trace or +trace={filename}: write a trace file {filename}.vcd
 *
 * The simulation driver reads commands from stdin (normally generated by Chisel tests).
 * If the +run argument is passed to the simulator, this code writes a temporary file with the appropriate commands
 * and replaces the stdin file descriptor with this file. By this, the simulation driver can read commands normally.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <climits>

#define RUN_FLAG "+run"
#define RUN_ARG "+run="
#define TRACE_FLAG "+trace"
#define TRACE_ARG "+trace="

// The simulation driver protocol allows only to advance INT_MAX cycles with one command.
// Running indefinitely is simplified to running for INT_MAX cycles.
#define MAX_CYCLES INT_MAX

static FILE *tmp = NULL;

// run before main()
__attribute__((constructor)) void simulation_driver_stimulus(void) {

  bool run = false;
  long long cycles = -1;
  bool trace = false;

  // read command line arguments
  FILE *cmdline = fopen("/proc/self/cmdline", "rb");
  if (!cmdline) {
    fprintf(stderr, "Could not read command line arguments.\n");
    return;
  }
  char *arg = NULL;
  size_t n = 0;
  ssize_t len;
  while ((len = getdelim(&arg, &n, '\0', cmdline)) != -1) {
    if (strncmp(RUN_FLAG, arg, strlen(arg)) == 0) {
      cycles = MAX_CYCLES;
      run = true;
    }
    if (strncmp(RUN_ARG, arg, strlen(RUN_ARG)) == 0) {
      char *num = arg + strlen(RUN_ARG);
      char* end = NULL;
      errno = 0;
      cycles = strtoll(num, &end, 10);
      if (errno == ERANGE) {
        fprintf(stderr, "Cycles to run for exceeds range (0 to %d).\n", MAX_CYCLES);
        exit(EXIT_FAILURE);
      }
      run = true;
    }
    if (strncmp(TRACE_FLAG, arg, strlen(arg)) == 0) {
      trace = true;
    }
    if (strncmp(TRACE_ARG, arg, strlen(TRACE_ARG)) == 0) {
      char *file = arg + strlen(TRACE_ARG);
      setenv("SVSIM_SIMULATION_TRACE", file, 1);
      trace = true;
    }
  }
  free(arg);
  fclose(cmdline);

  // write command file for the simulation driver to read from stdin
  if (!run) {
    fprintf(stderr, "Running Chisel simulation driver. Use +run[=cycles] for standalone simulation.\n");
    return;
  }
  if (cycles < 0 || cycles > MAX_CYCLES) {
    fprintf(stderr, "Cycles to run for exceeds range (0 to %d).\n", MAX_CYCLES);
    exit(EXIT_FAILURE);
  } else {
    tmp = tmpfile();
    if (tmp) {
      fprintf(tmp, "R a\nS 1 0\nR a\nS 1 1\nT 0 0,1-5*1\nS 1 0\nR 0\n"); // reset procedure

      if (trace) {
        fprintf(tmp, "W 1\n"); // activate trace
      }

      // toggle clock a number of cycles
      if (cycles > 0) {
        fprintf(tmp, "T 0 0,1-5*%x\n", cycles);
      }
      fprintf(tmp, "D\n");

      fseek(tmp, 0, SEEK_SET);
      dup2(fileno(tmp), STDIN_FILENO);

      setenv("SVSIM_SIMULATION_LOG", "/dev/null", 0);
    }
    return;
  }
}

// close temporary file
__attribute__((destructor)) void simulation_driver_stimulus_close(void) {
  if (tmp != NULL) {
    fclose(tmp);
  }
}
